#!/usr/bin/env node
/**
 * One-time enrollment for existing projects: detect each project's stack
 * (package.json / composer.json / Dockerfile) and generate a starter
 * per-project standards override, so every project has *something* in its
 * "Project Overrides" layer instead of starting blank.
 *
 * This only ever touches project_standards.override_md - it does not write
 * to any project's CLAUDE.md directly. The existing layered-standards flow
 * (mcp-server/standards.js, run at ticket-claim time) merges this override
 * with the org baseline and writes the result into the project's CLAUDE.md
 * as a managed block on the next ticket claimed for that project.
 *
 * Idempotent: a project counts as already enrolled once its override_md is
 * non-empty, and is skipped on subsequent runs (so a human's edits made via
 * the app's Standards tab are never clobbered by re-running this).
 *
 * Run standalone:  node mcp-server/bootstrap-standards.js
 */
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import { pool } from './db.js';
import { detectStack, describeStack } from './stack-detect.js';

const GENERATED_NOTE =
  'Auto-generated by mcp-server/bootstrap-standards.js from the detected stack. ' +
  'Edit freely from this project\'s Standards tab - re-running the bootstrap ' +
  'script will not overwrite a non-empty override.';

/** Build the starter override_md for a project from its detected stack. */
function generateOverride(projectFolder, facts) {
  const stackDescription = describeStack(facts);
  const body = stackDescription
    ? `## Detected Stack\n\n${stackDescription}`
    : '## Detected Stack\n\n- No `package.json`, `composer.json`, or `Dockerfile` found at the project root - ' +
      'stack could not be auto-detected. Replace this line with a manual description.';

  return `${body}\n\n_${GENERATED_NOTE}_`;
}

async function main() {
  const [projects] = await pool.query(
    `SELECT p.id, p.name, p.folder_path, ps.override_md
       FROM projects p
       LEFT JOIN project_standards ps ON ps.project_id = p.id
      WHERE p.folder_path IS NOT NULL AND p.folder_path <> ''
      ORDER BY p.id`
  );

  let enrolled = 0;
  let skipped = 0;

  for (const project of projects) {
    if (project.override_md && project.override_md.trim() !== '') {
      console.error(`[bootstrap-standards] "${project.name}" already enrolled - skipping.`);
      skipped++;
      continue;
    }
    if (!fs.existsSync(project.folder_path)) {
      console.error(`[bootstrap-standards] "${project.name}": folder_path ${project.folder_path} not found on this host - skipping.`);
      skipped++;
      continue;
    }

    const facts = detectStack(project.folder_path);
    const overrideMd = generateOverride(project.folder_path, facts);

    await pool.query(
      `INSERT INTO project_standards (project_id, override_md) VALUES (?, ?)
       ON DUPLICATE KEY UPDATE override_md = VALUES(override_md)`,
      [project.id, overrideMd]
    );
    console.error(`[bootstrap-standards] "${project.name}" enrolled.`);
    enrolled++;
  }

  console.error(`[bootstrap-standards] done - ${enrolled} enrolled, ${skipped} skipped.`);
  await pool.end();
}

// Only run when executed directly (`node bootstrap-standards.js`), never as
// a side effect of another module importing from this file.
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((err) => {
    console.error('[bootstrap-standards] error:', err.message);
    process.exit(1);
  });
}
